<?php
declare(strict_types=1);namespace Joomleague\Module\Competitions\Site\Helper;defined('_JEXEC')or die;use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\ProjectCatalogueReader;
final class CompetitionsHelper{/** @return list<object> */public function getCompetitions(Registry$p):array{$app=Factory::getApplication();$app->bootComponent('com_joomleague');$lang=Factory::getLanguage();$lang->load('com_joomleague',JPATH_SITE)||$lang->load('com_joomleague',JPATH_SITE.'/components/com_joomleague');try{return(new ProjectCatalogueReader(Factory::getContainer()->get(DatabaseInterface::class)))->read($app->getIdentity()->getAuthorisedViewLevels(),(int)$p->get('sport_type_id',0),(int)$p->get('season_id',0),(string)$p->get('organisation',''),max(1,min(100,(int)$p->get('limit',10))));}catch(\Throwable){return[];}}}
